# OWNER: (name)   ROLE: verifier   NEEDS: all results   WRITES: results["verification"] (and may correct results)
"""Cross-checks before the calculator: what is safe to bid, what must be omitted, and whether no_bid is justified.

results["verification"] = {"decision": "bid" | "no_bid", "omit": ["<pos>", ...], "issues": ["...", ...]}
Plain code: it only compares what the analyzers wrote; it never reads the websites or asks a model.
"""
from swarm import Agent, Phase, register
from swarm.facts import brief_facts, number


@register
class EvidenceVerifier(Agent):
    phase = Phase.VERIFY

    async def run(self) -> None:
        board = self.ctx.board
        facts = await brief_facts(self.ctx)
        result = verify(facts, board.get("quantities") or {}, board.get("requirements") or {},
                        board.get("materials") or {}, board.get("discount") or {})
        await board.set("verification", result)
        self.log.info("decision %s, omit %s, issues %s", result["decision"], result["omit"], result["issues"])


def verify(facts: dict, quantities: dict, requirements: dict, materials: dict, discount: dict) -> dict:
    issues, omit = [], []
    if not facts.get("tender_reference"):
        issues.append("no tender reference from the brief")
    positions = quantities.get("positions") or {}
    if not positions:
        issues.append("no tender positions")
    by_req = requirements.get("by_position") or {}
    by_mat = materials.get("by_position") or {}
    for pos, info in positions.items():
        problems = []
        if number(info.get("quantity")) is None:
            problems.append("quantity")
        if pos not in by_req:
            problems.append("requirement")
        elif (info.get("unit") or "").casefold().startswith("satz") and not by_req[pos].get("pieces_per_set"):
            problems.append("pieces per set")
        if not by_mat.get(pos):
            problems.append("material")
        if problems:
            omit.append(pos)
            issues.append(f"{pos}: missing {', '.join(problems)}")
    no_match = [p for p in materials.get("no_match") or [] if p in positions]
    decision = "no_bid" if no_match else "bid"
    if no_match:
        issues.append(f"no active matching material for {no_match}: no_bid")
    if number(discount.get("percent")) is None:
        issues.append("discount percent unreadable: 0 %")
    return {"decision": decision, "omit": sorted(set(omit)), "issues": issues}

