# Mail topics the rules engine resolves. The brief names who may send each (local part + bidder mailbox domain).
TOPICS = {
authorities: only for these topics, and only when the brief names the sender: {topics}"""


def plain(text) -> str:
    """Text without zero-width padding, whitespace collapsed."""
    return " ".join(str(text or "").translate(INVISIBLE).split())


def mask_secrets(brief: str, task: dict) -> str:
    """The brief with every login value replaced by a placeholder."""
    for site in task.get("access") or []:
        for key, value in (site.get("credentials") or {}).items():
            if isinstance(value, str) and len(value) >= 4:
                brief = brief.replace(value, f"<{key}>")
    return brief


def valid(name: str, value, brief: str) -> str | None:
    """The cleaned value if it has the field's format and is written in the brief, else None."""
    if not isinstance(value, str):
        return None
    value = plain(value).strip(" .,;`'\"")
    if not value or not re.fullmatch(FIELDS[name], value):
        return None
    return value if value in plain(brief) else None


def from_patterns(brief: str) -> dict:
    text = plain(brief)
    out = {}
    for name, pattern in PATTERNS.items():
        match = re.search(pattern, text)
        if match:
            out[name] = match.group(1)
    return out


